/***********************
 * Wallos payload 修复
 ***********************/
if (msg.payload && typeof msg.payload === "object") {
    // Wallos 的 JSON 被塞进了 key 里
    const jsonKey = Object.keys(msg.payload)
        .find(k => k.includes('"days_until"'));

    if (jsonKey) {
        try {
            const fixed = JSON.parse(`{${jsonKey}}`);
            msg.payload = fixed;
        } catch (e) {
            node.warn("Wallos payload 修复失败");
        }
    }
}

/***********************
 * 输出1：Miniflux Webhook
 ***********************/
if ("feed" in msg.payload) {
    return [msg, null, null, null, null, null];
}

/***********************
 * 输出2：MoviePilot
 ***********************/
else if ("data" in msg.payload) {

    // 普通通知
    if (
        "mediainfo" in msg.payload.data ||
        "context" in msg.payload.data ||
        "subscribe_id" in msg.payload.data
    ) {
        return [null, msg, null, null, null, null];
    }

    // 站点相关通知
    else if (
        "mtype" in msg.payload.data &&
        msg.payload.data.mtype?._value_ === "站点"
    ) {
        return [null, msg, null, null, null, null];
    }

    // 刷流插件通知
    else if (msg.payload.type === "plugin.triggered") {
        return [null, msg, null, null, null, null];
    }
}

/***********************
 * 输出3：DIUN
 ***********************/
else if ("diun_version" in msg.payload) {
    return [null, null, msg, null, null, null];
}

/***********************
 * 输出4：Wallos
 ***********************/
else if (msg.payload.days_until !== undefined) {
    return [null, null, null, msg, null, null];
}

/***********************
 * 输出5：Grafana
 ***********************/
else if ("alerts" in msg.payload) {
    return [null, null, null, null, msg, null];
}

/***********************
 * 输出n：未知来源
 ***********************/
else {
    msg.payload = context.get("error")?.payload ?? msg.payload;
    return [null, null, null, null, null, msg];
}

