// 格式化BiliBili直播RSS消息的标题
global.set("removeTimestamp", function (inputString) {
    // 使用正则表达式匹配日期时间格式 YYYY-MM-DD HH:MM:SS
    const regex = /\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;

    // 使用正则表达式替换掉时间部分
    const resultString = inputString.replace(regex, '').trim();  // `trim()` 用于去掉末尾的多余空格

    return resultString;
});

